var CASES = [
/* Published cases: each follows a peer-reviewed case report (pub). The facts, timeline and outcome come from the paper;
   the decision points, distractors and teaching points are added for teaching and need specialist review. */
{ id: "fpies-after-nec", engine: "nicu", track: "nicu", aud: ["paed", "diet"], level: "Advanced", min: 8,
  pub: { cite: "Lu Y, Zhang ZQ. Food protein-induced enterocolitis syndrome presenting after necrotizing enterocolitis in a preterm neonate: a case report. Transl Pediatr 2021;10(5):1393-8", url: "https://doi.org/10.21037/tp-21-9" },
  title: "Recurrent bloody stools in a preterm infant",
  sub: "Food protein-induced enterocolitis after NEC in a 28-week preterm baby",
  pt: { tag: "28 wk", name: "Baby boy, Lu 2021", line: "Born at 28 weeks by caesarean, 1,240 g. Preterm formula and expressed breast milk from day 2, advancing by 10 to 20 mL/kg/day." },
  vitals: [["GA", "28 wk"], ["Weight", "1,240 g"], ["Feeds", "EBM + formula"]],
  scene: { mode: "nicu", fill: .3, feeding: true, hr: 150, spo2: 95, temp: 36.8 },
  steps: [
   { s: "Day 7", v: "On 40 mL/kg/day he has apnoeas, larger gastric residuals, a distended, tender abdomen with sluggish bowel sounds and grossly bloody stools. CRP is raised and the white cell count is low. The X-ray shows pneumatosis intestinalis in the descending colon.",
     q: "What is the right response?",
     o: [["Treat as NEC: stop enteral feeds, decompress the stomach, take a blood culture, start broad-spectrum IV antibiotics and parenteral nutrition, support breathing and circulation, and involve the surgeons", "Pneumatosis with systemic signs is definite NEC.", 1],
         ["Switch to an amino acid formula and keep feeding", "Bloody stools with pneumatosis and systemic illness are NEC until proven otherwise; feeds must stop.", 0],
         ["Halve the feed volume and repeat the X-ray tomorrow", "Not enough for definite NEC.", 0],
         ["Give a glycerine suppository", "Does not treat NEC and delays care.", 0]],
     a: "The team managed this as NEC (reported as stage IIIA): feeds stopped, IV antibiotics started, and he needed ventilation and circulatory support. The blood culture grew E. coli and antibiotics were changed to match. Feeds with expressed breast milk restarted on day 15.",
     g: ["Lu Y, Zhang ZQ. FPIES presenting after NEC in a preterm neonate: a case report. Transl Pediatr 2021", "Neu J, Walker WA. Necrotizing enterocolitis. NEJM 2011", "Walsh MC, Kliegman RM. Necrotizing enterocolitis: treatment based on staging criteria. Pediatr Clin North Am 1986"],
     p: "Pneumatosis plus systemic signs: treat as NEC first.",
     pre: { mode: "gut", feeding: true, fill: .3, distension: .7, stress: .5, colour: "red", stool: "normal", hr: 178, spo2: 89, alarm: true },
     fx: { ok: { cap: "Feeds stopped, stomach decompressed, antibiotics and support started.", set: { feeding: false, fill: .02, distension: .45, stress: .3, hr: 166, spo2: 93, alarm: false }, mode: "gut", hl: "gut" }, bad: { cap: "Feeding through NEC: the bowel distends further.", set: { feeding: true, distension: 1, stress: .9, hr: 192, spo2: 84, alarm: true }, mode: "gut", hl: "gut", kind: "bad" } } },
   { s: "Day 29", v: "His mother's supply has fallen, so preterm formula is added. Two weeks after feeds restarted he passes bloody stools again, but he looks well: soft, non-tender abdomen, active bowel sounds, normal CRP and white cell count. The X-ray shows only mild small-bowel wall thickening, without pneumatosis.",
     q: "What should this pattern make you consider?",
     o: [["A reaction to cow's milk protein (food protein-induced enterocolitis) alongside NEC: bleeding after a new cow's milk exposure in a well baby with normal markers and no pneumatosis", "The picture differs from the first episode, and the feeds have changed.", 1],
         ["Certain recurrent NEC; nothing else needs considering", "Recurrent NEC is possible, but a well baby with normal markers after a new cow's milk exposure needs a wider differential.", 0],
         ["Swallowed maternal blood", "Not plausible on day 29 in a tube-fed baby.", 0],
         ["Haemorrhagic disease of the newborn; give vitamin K and carry on", "Does not fit this picture.", 0]],
     a: "The team treated this as recurrent NEC: feeds were stopped for 3 days and antibiotics given until the blood culture came back negative. The authors point to features that separate FPIES from NEC: a well-looking baby, normal inflammatory markers, no progression of systemic signs, a link in time to cow's milk protein, and quick improvement once it is removed. Mistaking FPIES for NEC leads to repeated fasting, antibiotics and longer stays.",
     g: ["Lu Y, Zhang ZQ. Transl Pediatr 2021", "Nowak-Węgrzyn A et al. International consensus guidelines for the diagnosis and management of FPIES. J Allergy Clin Immunol 2017"],
     p: "Before every recurrence of bloody stools, ask what changed in the feeds.",
     pre: { mode: "inside", feeding: true, fill: .4, distension: .1, stress: .1, colour: "red", stool: "normal", hr: 150, spo2: 96, alarm: false },
     fx: { ok: { cap: "The cow's milk exposure is flagged as a possible trigger.", hl: "gut" }, bad: { cap: "A second course of empirical NEC treatment; the trigger stays in the feeds.", set: { feeding: false, fill: .05 }, kind: "warn" } } },
   { s: "Days 46 and 54", v: "Day 46: expressed breast milk at 140 mL/kg/day with a cow's milk-based fortifier is followed by bloody stools in a well baby, with a mild rise in eosinophils. Day 54: preterm formula is tried again. He develops distension and grossly bloody stools; eosinophils are 13.8%, and CRP and white cell count are normal.",
     q: "What is the best feeding plan now?",
     o: [["Remove cow's milk protein: mother's own milk with a fortifier that is not cow's milk-based where available, an extensively hydrolysed formula if milk runs short, and lactation support to rebuild supply", "Removes the trigger and keeps human milk first.", 1],
         ["Continue the same formula and give antibiotics with each episode", "Keeps the trigger and repeats unnecessary antibiotics.", 0],
         ["Keep him nil by mouth on parenteral nutrition until discharge", "Long parenteral nutrition adds line infection and cholestasis risk.", 0],
         ["Switch to a lactose-free cow's milk formula", "Lactose-free formulas still contain intact cow's milk protein.", 0]],
     a: "After a day of fasting, the team fed breast milk fortified without cow's milk. After the day 54 episode the formula was changed to a hydrolysed formula and the symptoms settled; bloody stools did not recur on expressed breast milk. FPIES guidance is to remove the trigger food. The guideline notes that breastfeeding should continue where possible, that most infants with cow's milk FPIES tolerate an extensively hydrolysed formula, and that 10% to 20% need an amino acid formula.",
     g: ["Lu Y, Zhang ZQ. Transl Pediatr 2021", "Nowak-Węgrzyn A et al. J Allergy Clin Immunol 2017", "Vandenplas Y et al. ESPGHAN position paper on cow's milk allergy. JPGN 2024"],
     p: "Breast milk is rarely the problem; the cow's milk protein added to it can be.",
     dp: "Chart fortifier and formula changes next to stools and eosinophils. Plan protein and energy targets with a fortifier that is not cow's milk-based, and support expressing to protect supply.",
     pre: { mode: "inside", feeding: true, fill: .45, distension: .35, stress: .3, colour: "red", stool: "normal", hr: 158 },
     fx: { ok: { cap: "Trigger removed: stools clear and feeds advance.", set: { colour: "normal", distension: 0, stress: .05, hr: 146, feeding: true, fill: .5 }, mode: "inside", hl: "stomach" }, bad: { cap: "The trigger stays: bleeding and distension return.", set: { colour: "red", distension: .5, stress: .45, hr: 170 }, mode: "gut", hl: "gut", kind: "bad" } } },
   { s: "Going home", v: "Day 60. He is feeding well on expressed breast milk with no more bleeding. His mother wants to breastfeed at home and asks about cow's milk later on.",
     q: "What is the best discharge plan?",
     o: [["Continue breastfeeding, avoid cow's milk-based formula, give the family an emergency treatment plan, and plan a supervised cow's milk challenge later", "Matches the outcome and current FPIES guidance.", 1],
         ["Start a standard cow's milk formula at home to build tolerance", "Unsupervised re-exposure risks a severe reaction.", 0],
         ["Stop breastfeeding to be safe", "Expressed breast milk caused no reactions; breastfeeding should continue.", 0],
         ["Use specific IgE tests alone to decide when to reintroduce at home", "FPIES is non-IgE-mediated, so IgE tests cannot replace a supervised challenge; the guideline suggests considering them only because IgE sensitisation predicts more persistent disease.", 0]],
     a: "He went home after 60 days in hospital and was breastfed for 8 months with no further bloody stools. The international FPIES guideline advises avoiding the trigger, emergency treatment planning, nutritional support and a supervised oral food challenge to check for resolution; in the United States this is usually attempted 12 to 18 months after the most recent reaction.",
     g: ["Lu Y, Zhang ZQ. Transl Pediatr 2021", "Nowak-Węgrzyn A et al. J Allergy Clin Immunol 2017"],
     p: "Write the trigger, the plan and the follow-up date in the discharge summary.",
     pre: { mode: "nicu", feeding: true, fill: .4, distension: 0, stress: 0, colour: "normal", hr: 144, spo2: 97, alarm: false },
     fx: { ok: { cap: "Home on breast milk, with a plan.", set: {} }, bad: { cap: "Re-exposure at home risks another reaction.", kind: "warn" } } }
  ],
  refs: ["Lu Y, Zhang ZQ. Food protein-induced enterocolitis syndrome presenting after necrotizing enterocolitis in a preterm neonate: a case report. Transl Pediatr 2021;10:1393-8", "Nowak-Węgrzyn A et al. International consensus guidelines for the diagnosis and management of food protein-induced enterocolitis syndrome. J Allergy Clin Immunol 2017;139:1111-26", "Neu J, Walker WA. N Engl J Med 2011;364:255-64", "Walsh MC, Kliegman RM. Pediatr Clin North Am 1986;33:179-201", "Vandenplas Y et al. J Pediatr Gastroenterol Nutr 2024;78:386-413"] },

{ id: "ccd-preterm", engine: "nicu", track: "fluid", aud: ["paed", "diet"], level: "Advanced", min: 8,
  pub: { cite: "Cendal I et al. Prenatal and postnatal manifestations of congenital chloride diarrhea due to a heterozygote variant of the SLC26A3 gene: a case report. Front Pediatr 2021;9:758006", url: "https://doi.org/10.3389/fped.2021.758006" },
  title: "Polyhydramnios, abdominal distension and watery stools",
  sub: "Congenital chloride diarrhoea in a 32-week preterm baby, first mistaken for bowel obstruction",
  pt: { tag: "32 wk", name: "Baby boy, Cendal 2021", line: "Born at 32+4 weeks by emergency caesarean, 2,260 g. Polyhydramnios needed amnioreduction at 28 weeks; antenatal scans showed dilated, fluid-filled bowel loops." },
  vitals: [["GA", "32+4 wk"], ["Weight", "2,260 g"], ["Day 1 loss", "15%"]],
  scene: { mode: "nicu", distension: .55, stool: "watery", fill: .05, feeding: false, stress: .35, hr: 156, spo2: 95, temp: 36.7 },
  steps: [
   { s: "Birth", v: "The abdomen is distended and no meconium is passed; a rectal washout returns only watery fluid. He loses 340 g (15%) on day 1. The X-ray shows fluid levels suggesting low bowel obstruction, and a laparotomy on day 2 finds nothing wrong in the abdomen.",
     q: "Looking back, which combination points to a congenital secretory diarrhoea rather than an obstruction?",
     o: [["Polyhydramnios with dilated, fluid-filled bowel loops before birth, watery rectal output instead of meconium, and a large early weight loss", "Fetal diarrhoea fills the bowel and the amniotic sac with fluid.", 1],
         ["Abdominal distension alone", "Distension is common to both obstruction and congenital diarrhoea.", 0],
         ["Prematurity alone", "Here preterm birth followed the polyhydramnios; it does not point to a cause.", 0],
         ["Bile-stained vomiting", "Points to malrotation or a proximal obstruction; it was not part of this picture.", 0]],
     a: "In congenital chloride diarrhoea, watery diarrhoea before birth causes polyhydramnios, dilated fluid-filled bowel and preterm birth, and the newborn's distended abdomen without meconium can mimic obstruction. At laparotomy this baby's bowel was evenly distended with air and clear fluid. The authors note that the watery stools are often confused with urine, which delays diagnosis; here it was first considered on day 20.",
     g: ["Cendal I et al. Congenital chloride diarrhea: a case report. Front Pediatr 2021", "Wedenoja S, Höglund P, Holmberg C. Review article: the clinical management of congenital chloride diarrhoea. Aliment Pharmacol Ther 2010"],
     p: "Polyhydramnios plus a fluid-filled bowel on the scan: think congenital diarrhoea before theatre.",
     pre: { mode: "nicu", distension: .55, stool: "watery", stress: .35, hr: 160 },
     fx: { ok: { cap: "The pattern is named: watery losses, not a blockage.", set: {}, mode: "gut", hl: "gut" }, bad: { cap: "The search for an obstruction goes on while fluid pours out.", set: { stress: .5, hr: 170 }, mode: "gut", hl: "gut", kind: "warn" } } },
   { s: "Day 20", v: "Feeds have been mainly oral since day 7, and a marked hypochloraemic metabolic alkalosis has developed. No obvious diarrhoea was seen; constipation was even suspected, but rectal catheterisation released a large amount of stool. Cystic fibrosis has been excluded by genetic testing.",
     q: "Which test best supports congenital chloride diarrhoea?",
     o: [["Faecal chloride (above 90 mmol/L once fluid and salt losses are corrected), then SLC26A3 gene testing", "High stool chloride with metabolic alkalosis is the hallmark; genetics confirms it.", 1],
         ["Stool culture for bacteria and viruses", "Infection would not explain a hypochloraemic metabolic alkalosis.", 0],
         ["Serum gastrin", "Not diagnostic.", 0],
         ["Contrast enema", "Imaging cannot show a transport defect.", 0]],
     a: "Most diarrhoea causes acidosis; stool losses with metabolic alkalosis point to chloride loss in the stool. The authors describe a faecal chloride above 90 mmol/L as pathognomonic and note it is rarely measured, which delays diagnosis; diagnosis rests on high faecal chloride once serum electrolytes are corrected, confirmed by genetic testing. In this baby, next-generation sequencing found a homozygous SLC26A3 variant (c.2024_2026dupTCA), and both parents were carriers.",
     g: ["Wedenoja S et al. Aliment Pharmacol Ther 2010", "Cendal I et al. Front Pediatr 2021"],
     p: "Diarrhoea with alkalosis: measure the stool chloride.",
     pre: { mode: "inside", stool: "watery", distension: .2, fill: .3, feeding: true, stress: .3, hr: 158 },
     fx: { ok: { cap: "Stool chloride and genetics confirm the diagnosis.", hl: "gut" }, bad: { cap: "The salt-losing cause stays hidden.", kind: "warn" } } },
   { s: "Treatment", v: "The diagnosis is confirmed.",
     q: "What is the mainstay of treatment?",
     o: [["Lifelong oral sodium chloride and potassium chloride, adjusted to keep serum electrolytes and acid-base balance normal", "Replacing what is lost prevents dehydration and electrolyte disturbance.", 1],
         ["Sodium bicarbonate to replace the losses", "Bicarbonate worsens the metabolic alkalosis.", 0],
         ["Restrict fluids to reduce the stool output", "Restriction deepens salt and water depletion.", 0],
         ["Loperamide to stop the diarrhoea", "Antimotility drugs do not fix the transport defect and are unsafe in infants.", 0]],
     a: "Life-long salt substitution with NaCl and KCl stabilises fluid, electrolyte and acid-base balance, and the long-term outcome is favourable when treatment is right. Untreated disease can be fatal in the first weeks. In this case NaCl and KCl started on day 20, a sepsis episode followed, parenteral nutrition stopped at 50 days, and he went home after 61 days on feeds with added 0.9% saline.",
     g: ["Wedenoja S et al. Aliment Pharmacol Ther 2010", "Cendal I et al. Front Pediatr 2021"],
     p: "Treat the salt loss, not the stool count.",
     dp: "Add the prescribed salt to each feed, recalculate as weight rises, and chart weight, stool output and urinary chloride.",
     pre: { mode: "inside", stool: "watery", fill: .4, feeding: true, stress: .25, hr: 154 },
     fx: { ok: { cap: "Salt replaced: the alkalosis corrects and weight climbs, though stools stay loose.", set: { stress: .05, hr: 142, distension: 0 }, mode: "inside", hl: "stomach" }, bad: { cap: "Electrolytes keep swinging and he does not grow.", set: { stress: .5, hr: 168 }, kind: "bad" } } },
   { s: "Follow-up", v: "At 6 months he is growing well with normal electrolytes, and passes up to 12 soft stools a day.",
     q: "What should the family be told?",
     o: [["Frequent loose stools are expected; keep giving the salt, and get help early in any illness with fever, vomiting or more diarrhoea, because salt and water needs rise quickly", "Intercurrent illness is the main danger.", 1],
         ["Stop the salt once the stools are soft", "Replacement is lifelong.", 0],
         ["Stools should be normal by now; investigate further", "Ongoing loose stools are expected.", 0],
         ["Avoid salt in the diet", "The opposite of what he needs.", 0]],
     a: "Children with congenital chloride diarrhoea keep having loose stools; with proper treatment the long-term outcome is favourable. The review highlights managing acute dehydration and hypokalaemia during gastroenteritis or other infections, and the case authors stress keeping vaccinations up to date to avoid infections that can cause life-threatening dehydration. This infant also had nappy dermatitis, heavy sweating and neurological findings at 6 months, so follow-up was multidisciplinary.",
     g: ["Wedenoja S et al. Aliment Pharmacol Ther 2010", "Cendal I et al. Front Pediatr 2021"],
     p: "Give the family a written sick-day plan.",
     pre: { mode: "nicu", stool: "watery", fill: .4, feeding: true, stress: 0, distension: 0, hr: 138 },
     fx: { ok: { cap: "The family know what is normal and when to come in.", set: {} }, bad: { cap: "Without a sick-day plan, the next tummy bug is dangerous.", kind: "warn" } } }
  ],
  refs: ["Cendal I, Szafrańska A, Fuchs T, Patkowski D, Smigiel R, Królak-Olejnik B. Prenatal and postnatal manifestations of congenital chloride diarrhea due to a heterozygote variant of the SLC26A3 gene: a case report. Front Pediatr 2021;9:758006", "Wedenoja S, Höglund P, Holmberg C. Review article: the clinical management of congenital chloride diarrhoea. Aliment Pharmacol Ther 2010;31:477-85"] },

{ id: "ors-hypernatraemia", engine: "home", track: "fluid", aud: ["paed", "diet"], level: "Advanced", min: 7,
  pub: { cite: "Das SK et al. Extreme hypernatremic dehydration due to potential sodium intoxication: consequences and management for an infant with diarrhea at an urban intensive care unit in Bangladesh: a case report. J Med Case Rep 2015;9:124", url: "https://doi.org/10.1186/s13256-015-0611-y" },
  title: "Lethargy and extreme thirst during acute diarrhoea",
  sub: "Extreme hypernatraemic dehydration after wrongly mixed ORS in a 6-month-old with diarrhoea",
  pt: { tag: "6 mo", name: "Baby girl, Das 2015", line: "6-month-old girl, 5.9 kg, breastfed with diluted formula. Watery diarrhoea 12 to 15 times a day for 2 days, fever, lethargic for 12 hours." },
  vitals: [["Age", "6 mo"], ["Weight", "5.9 kg"], ["Feeding", "BF + formula"]],
  scene: { view: "outside", stool: "watery", stress: .35, sleepy: .7, fill: .2, hr: 134, temp: 39.4 },
  steps: [
   { s: "Triage", v: "At triage she was recorded as having no signs of dehydration, but a nurse thought she looked abnormally ill. She is lethargic, irritable when touched and extremely thirsty; capillary refill is 3 seconds and temperature 39.4°C. At home she drank ORS instead of her usual feeds, and a packet of rice-based ORS had been made up in 500 mL of water instead of 1,100 mL.",
     q: "What is the most important next step?",
     o: [["Suspect hypernatraemic dehydration and check the serum sodium urgently", "Lethargy, irritability on touch and intense thirst with few classic signs is typical of hypernatraemia.", 1],
         ["Classify as no dehydration and send her home on ORS", "Classic signs are masked in hypernatraemia, and lethargy is a danger sign.", 0],
         ["Give an antidiarrhoeal and review tomorrow", "Antimotility drugs are not recommended, and this is an emergency.", 0],
         ["Give a fast bolus of hypotonic fluid before any tests", "Rapid hypotonic fluid risks cerebral oedema in hypernatraemia.", 0]],
     a: "In hypernatraemia, water moves out of the cells, so the circulation and skin can look deceptively normal while the brain is affected. Her serum sodium was 208 mmol/L. The WHO manual notes that hypernatraemic dehydration develops especially when children are given hypertonic drinks with too much sugar or salt.",
     g: ["Das SK et al. Extreme hypernatremic dehydration: a case report. J Med Case Rep 2015", "WHO. The treatment of diarrhoea: a manual for physicians and other senior health workers (2005)"],
     p: "A lethargic, very thirsty child with diarrhoea needs a sodium level, whatever the skin pinch shows.",
     pre: { view: "outside", stool: "watery", stress: .35, hr: 134 },
     fx: { ok: { cap: "Sodium 208 mmol/L: extreme hypernatraemia.", set: { view: "inside" }, hl: "gut" }, bad: { cap: "A lethargic baby nearly goes home.", kind: "bad" } } },
   { s: "Correction", v: "Sodium 208 mmol/L and calcium low. She is perfusing well and can take fluid by nasogastric tube.",
     q: "How fast should the sodium come down?",
     o: [["Slowly, aiming for a fall of no more than 10 mmol/L in 24 hours with frequent sodium checks; this team gave calculated ORS by nasogastric tube", "Slow correction protects the brain.", 1],
         ["Back to normal within 6 hours", "Rapid falls cause cerebral oedema and seizures.", 0],
         ["Plain water by bottle, as much as she wants", "Free water drops sodium unpredictably fast.", 0],
         ["Nothing until she passes urine", "Delays treatment of a life-threatening state.", 0]],
     a: "The brain adapts to hypernatraemia; if sodium then falls fast, water moves into brain cells. The team calculated the ORS volume with a sodium formula, aiming for a fall of no more than 10 mmol/L in 24 hours, and corrected the low calcium with IV calcium gluconate. A blood culture later grew Enterobacter, treated with ciprofloxacin.",
     g: ["Das SK et al. J Med Case Rep 2015"],
     p: "Write the target fall per 24 hours on the chart, with the time of the next sodium.",
     dp: "Calculate the ORS volume from weight, reassess every few hours, and restart breastfeeding as soon as she is alert.",
     pre: { view: "inside", stool: "watery", fill: .2, stress: .4, hr: 134 },
     fx: { ok: { cap: "Fluid by nasogastric tube; sodium falling slowly.", set: { feeding: true, fill: .45, stress: .25 }, hl: "stomach" }, bad: { cap: "A fast fall in sodium: the brain swells.", set: { stress: .85, hr: 170 }, kind: "bad" } } },
   { s: "24 hours", v: "Sodium is now 174 mmol/L: a fall of 34 mmol/L in a day, and still dropping by more than 0.5 mmol/L an hour.",
     q: "What do you do?",
     o: [["Slow the fall: recalculate and cut the fluid, add sodium, check sodium more often and watch closely for seizures", "The fall is far faster than planned.", 1],
         ["Carry on, as she is improving", "The fall already exceeds the safe rate.", 0],
         ["Switch to plain water to finish quickly", "Would speed the fall further.", 0],
         ["Give furosemide", "Not indicated.", 0]],
     a: "The team recalculated the ORS and added salt (1 g/L) to her diet. On day 3 she still had a generalised tonic-clonic seizure, controlled with lorazepam, phenobarbitone and phenytoin; sodium was normal by about 72 hours. MRI at discharge showed cerebral oedema, but MRI and EEG were normal 3 months later.",
     g: ["Das SK et al. J Med Case Rep 2015"],
     p: "Correction speed is a dose: chart it like one.",
     pre: { view: "inside", stool: "watery", fill: .45, feeding: true, stress: .25, hr: 140 },
     fx: { ok: { cap: "Correction slowed and she is watched closely; the seizure is treated fast.", set: { stress: .2, hr: 138 }, hl: "stomach" }, bad: { cap: "Sodium keeps plunging, and seizures follow.", set: { stress: .9, hr: 176 }, kind: "bad" } } },
   { s: "Prevention", v: "Before discharge, her mother asks what to do the next time her baby has diarrhoea.",
     q: "What advice would have prevented this admission?",
     o: [["Show her how to mix ORS with exactly the volume of clean water on the packet, give it alongside continued breastfeeding and feeds, add zinc, and come back if the baby becomes very thirsty, drinks poorly, develops a fever or is unusually sleepy", "Correct mixing and continued feeding protect against hypernatraemia.", 1],
         ["Use extra powder to make the ORS stronger", "Concentrated ORS causes hypernatraemia.", 0],
         ["Replace milk feeds with ORS only", "Feeding should continue; ORS in place of feeds contributed here.", 0],
         ["Avoid ORS and give plain water", "Water does not replace lost salts.", 0]],
     a: "The family had been told to give ORS but were never shown how to prepare it, and she had ORS in place of her usual diet. The WHO manual asks health workers to show the mother how to prepare ORS, to continue feeding, to give zinc, and to teach the signs that mean the child should be brought back, such as becoming very thirsty, eating or drinking poorly, or fever.",
     g: ["Das SK et al. J Med Case Rep 2015", "WHO 2005 diarrhoea treatment manual", "WHO/UNICEF joint statement: clinical management of acute diarrhoea (2004)"],
     p: "Don't just prescribe ORS: watch the family make up one packet.",
     pre: { view: "outside", stool: "normal", stress: .05, hr: 126, feeding: false },
     fx: { ok: { cap: "A demonstration in the family's own cup.", set: {} }, bad: { cap: "The same mistake can happen next time.", kind: "warn" } } }
  ],
  refs: ["Das SK, Afroze F, Ahmed T et al. Extreme hypernatremic dehydration due to potential sodium intoxication: consequences and management for an infant with diarrhea at an urban intensive care unit in Bangladesh: a case report. J Med Case Rep 2015;9:124", "WHO. The treatment of diarrhoea (2005)", "WHO/UNICEF joint statement on the clinical management of acute diarrhoea (2004)"] },
{ id: "pale-yellow-stools", engine: "home", track: "liver", aud: ["paed", "diet"], level: "Core", min: 7,
  pub: { cite: "Couturier L, Jarvis C, Rousseau H, Jimenez V. Biliary atresia. Can Fam Physician 2015;61(11):965-8", url: "https://pmc.ncbi.nlm.nih.gov/articles/PMC4642905/" },
  title: "Persistent jaundice in a thriving infant",
  sub: "Biliary atresia diagnosed at 11 weeks after six professionals saw a well, growing baby",
  pt: { tag: "2 d to 11 wk", name: "Baby boy, Couturier 2015", line: "Term boy, 3.77 kg, breastfed, followed in a university family medicine unit. Mildly jaundiced on day 2." },
  vitals: [["Born", "39+2 wk"], ["Weight", "3.77 kg"], ["Feeding", "Breastfed"]],
  scene: { view: "outside", jaundice: .35, colour: "normal", stool: "normal", hr: 140, temp: 36.8 },
  steps: [
   { s: "Day 2", v: "Mild jaundice: total bilirubin 195 μmol/L, below the treatment threshold. The conjugated bilirubin is 9 μmol/L, slightly above the laboratory's normal range of 0 to 5. Weight loss is 4.8%. He is ready for discharge.",
     q: "What should happen to the conjugated bilirubin result?",
     o: [["Make sure the abnormal result reaches the clinician who will follow him, and arrange a repeat conjugated bilirubin", "An abnormal conjugated level needs an owner and a plan.", 1],
         ["Nothing: the total bilirubin is below the treatment line", "Treatment nomograms ignore conjugated bilirubin; that is exactly how this result was lost.", 0],
         ["Start phototherapy before discharge", "Phototherapy treats unconjugated bilirubin, not cholestasis.", 0],
         ["Advise the mother to stop breastfeeding for 48 hours", "Unnecessary and harmful to breastfeeding.", 0]],
     a: "In this case no follow-up was requested for the raised conjugated level, the result was not sent to the mother or the community physician, and later clinicians were reassured by the mother's report that the bilirubin was normal. The authors point out that the nursery's jaundice guideline did not take conjugated bilirubin into account, and that early measurement of conjugated bilirubin can separate biliary atresia from benign breast milk jaundice.",
     g: ["Couturier L et al. Biliary atresia. Can Fam Physician 2015"],
     p: "Every abnormal result needs a named person to act on it.",
     pre: { view: "outside", jaundice: .35, colour: "normal" },
     fx: { ok: { cap: "The result has an owner and a repeat test is booked.", set: { jaundice: .3 } }, bad: { cap: "The one early clue leaves the hospital unseen.", kind: "warn" } } },
   { s: "Day 45", v: "At day 41 the mother phoned about jaundice; the nurse noted good breastfeeding and soft yellow stools. At day 45 the sclerae and skin are yellow. He is gaining weight well and looks well, and breast milk jaundice is diagnosed, with review in a month.",
     q: "What should have happened at this visit?",
     o: [["Jaundice beyond 2 weeks: measure total and conjugated bilirubin now and check the stool colour against a stool colour card", "Prolonged jaundice needs a conjugated bilirubin, however well the baby looks.", 1],
         ["Reassure: a thriving baby cannot have liver disease", "Babies with biliary atresia usually look well and grow normally early on.", 0],
         ["Review in a month if still yellow", "A month is a long time when Kasai timing matters.", 0],
         ["Advise sunlight exposure", "Not a treatment for cholestasis, and it delays diagnosis.", 0]],
     a: "Guidelines advise a conjugated (or direct) bilirubin in any infant still jaundiced after 2 weeks. The authors note that clinicians were reassured because the baby was thriving, and that several of them recorded the stools as 'yellow'; a stool colour card could have helped both professionals and parents recognise them as pale yellow, and therefore abnormal.",
     g: ["Couturier L et al. Can Fam Physician 2015", "Fawaz R et al. Guideline for the evaluation of cholestatic jaundice in infants: NASPGHAN and ESPGHAN. JPGN 2017", "NICE CG98. Jaundice in newborn babies under 28 days (2010, updated 2023)"],
     p: "Thriving does not rule out cholestasis.",
     pre: { view: "outside", jaundice: .65, colour: "normal" },
     fx: { ok: { cap: "Bloods today and a look at the stool colour card.", set: { view: "inside", colour: "pale", jaundice: .7 }, hl: "gut" }, bad: { cap: "Another month passes.", set: { jaundice: .8 }, kind: "bad" } } },
   { s: "Day 76", v: "Seen at a planned visit: normal development and weight gain, but marked jaundice, pale yellow stools, dark urine and an enlarged liver. Two days later: total bilirubin 169 μmol/L, conjugated 105 μmol/L, ALT 149 IU/L, AST 209 IU/L.",
     q: "What is the right next step?",
     o: [["Same-day referral to the paediatric gastroenterology or hepatology team for urgent biliary atresia work-up", "Conjugated hyperbilirubinaemia with pale stools is time-critical.", 1],
         ["Repeat the bloods in 2 weeks", "Every week of delay worsens the outcome of a Kasai operation.", 0],
         ["Start ursodeoxycholic acid and review", "Does not replace diagnosis and surgery.", 0],
         ["Switch to formula", "Feeding is not the problem.", 0]],
     a: "The family physician discussed the results with the on-call paediatric gastroenterologist and sent the baby for urgent work-up, which confirmed biliary atresia. The Kasai portoenterostomy was done at 83 days, with marked fibrosis of the biliary remnants. The jaundice cleared over 3 to 4 weeks, but he had three episodes of cholangitis in the following months. Outcomes after Kasai are better when it is done earlier.",
     g: ["Couturier L et al. Can Fam Physician 2015", "Serinet MO et al. Impact of age at Kasai operation on its results in late childhood and adolescence. Pediatrics 2009"],
     p: "Pale stools plus conjugated jaundice: refer the same day.",
     pre: { view: "inside", jaundice: .85, colour: "pale", stool: "normal" },
     fx: { ok: { cap: "Referred the same day; Kasai at 83 days.", hl: "gut" }, bad: { cap: "More fibrosis while the family waits.", kind: "bad" } } },
   { s: "Fix the system", v: "In 3 months he was seen by three nurses and three physicians. The abnormal day-2 result was never passed on, and there was no stool colour card in use.",
     q: "Which change would most help catch the next baby earlier?",
     o: [["Stool colour cards for parents and staff, a rule that prolonged jaundice triggers a conjugated bilirubin, and a way to send abnormal results to the family's own clinician", "Addresses each failure in this case.", 1],
         ["Routine liver ultrasound for every newborn", "Not an effective screening approach.", 0],
         ["More phototherapy in the nursery", "Irrelevant to cholestasis.", 0],
         ["Leave it to parents to report jaundice", "The mother did report it, twice.", 0]],
     a: "The authors attribute the delay to the rarity of the disease, no stool colour card screening, no institutional policy on following up neonatal jaundice, no electronic record, and fragmented care. Their unit has since trained staff to use stool colour charts. National stool colour card screening in Taiwan increased the proportion of babies having the Kasai operation before 60 days of age.",
     g: ["Couturier L et al. Can Fam Physician 2015", "Hsiao CH et al. Universal screening for biliary atresia using an infant stool color card in Taiwan. Hepatology 2008"],
     p: "Put a stool colour card in every discharge pack.",
     dp: "After Kasai, plan fat-soluble vitamins and energy-dense feeds with the hepatology team, and track growth closely.",
     pre: { view: "outside", jaundice: .4, colour: "normal" },
     fx: { ok: { cap: "A card, a rule and a result that reaches the right person.", set: { jaundice: .2 } }, bad: { cap: "The same gaps remain for the next baby.", kind: "warn" } } }
  ],
  refs: ["Couturier L, Jarvis C, Rousseau H, Jimenez V. Biliary atresia. Can Fam Physician 2015;61:965-8", "Fawaz R et al. J Pediatr Gastroenterol Nutr 2017;64:154-68", "NICE CG98", "Serinet MO et al. Pediatrics 2009;123:1280-6", "Hsiao CH et al. Hepatology 2008;47:1233-40"] },

{ id: "benign-proctocolitis", engine: "home", track: "allergy", aud: ["paed", "diet"], level: "Core", min: 7,
  pub: { cite: "Gelsomino M, Sinatti D, Miceli Sopo S. Non-allergic benign infantile proctocolitis: a neglected nosographic entity. BMJ Case Rep 2021;14:e244918", url: "https://doi.org/10.1136/bcr-2021-244918" },
  title: "Blood-streaked stools in a breastfed infant",
  sub: "Months of maternal elimination diets for rectal bleeding that turned out not to be food-related",
  pt: { tag: "5 wk to 4 mo", name: "Baby girl, Gelsomino 2021", line: "Exclusively breastfed girl, well and healthy-appearing. Rectal bleeding with mucus from 1 month 8 days of age." },
  vitals: [["Onset", "5 wk"], ["Feeding", "EBF"], ["Hb", "125 g/L"]],
  scene: { view: "outside", colour: "red", stool: "normal", hr: 138, temp: 36.8 },
  steps: [
   { s: "First month of bleeding", v: "From 1 month 8 days she passes bright blood, sometimes with mucus, in her stools. She is exclusively breastfed, healthy-appearing and growing, with no warning signs.",
     q: "What is the best first approach?",
     o: [["Examine for an anal fissure and warning signs, keep breastfeeding with no diet change, and review", "In a well infant, observation comes first.", 1],
         ["Start a strict cow's milk-free diet for the mother straight away", "Elimination diets are often started too early in well babies with minor bleeding.", 0],
         ["Switch to an amino acid formula", "Breastfeeding should continue.", 0],
         ["Arrange colonoscopy", "Not indicated in a well infant without warning signs.", 0]],
     a: "After a month of bleeding her mother started a cow's milk-free diet. ESPGHAN advises observation during the first month of bleeding in mild proctocolitis while encouraging breastfeeding. The case authors go further: in a healthy infant under 6 months with small amounts of bright blood for less than 2 months, no fissure and no warning signs, they would wait at least 2 months before eliminating any food.",
     g: ["Gelsomino M et al. Non-allergic benign infantile proctocolitis. BMJ Case Rep 2021", "Vandenplas Y et al. ESPGHAN position paper on cow's milk allergy. JPGN 2024"],
     p: "A well baby with streaks of blood: look, then wait.",
     pre: { view: "outside", colour: "red" },
     fx: { ok: { cap: "Breastfeeding continues and the baby is watched.", hl: "gut" }, bad: { cap: "A restrictive diet starts that may not be needed.", kind: "warn" } } },
   { s: "Skin prick tests", v: "On the mother's cow's milk-free diet the bleeding continues, up to five times a day. At 3 months 18 days, skin prick tests are negative for cow's milk and soy and positive for egg.",
     q: "What does the positive egg test tell you?",
     o: [["Sensitisation only: skin prick tests do not diagnose a non-IgE proctocolitis", "Only elimination followed by reintroduction can show a food is the cause.", 1],
         ["Egg allergy is confirmed and egg must be avoided for life", "Sensitisation is not allergy, and the bleeding is not IgE-mediated.", 0],
         ["The baby will react to egg on first exposure", "Not predictable from this test in this setting.", 0],
         ["Cow's milk is ruled out as a cause", "A negative prick test cannot rule out a non-IgE reaction either.", 0]],
     a: "The team advised reintroducing cow's milk and removing egg and soy. The mother removed egg but, out of fear, did not reintroduce cow's milk. ESPGHAN states that specific IgE and skin prick tests show sensitisation but do not confirm allergy, which is diagnosed from symptoms on elimination and reintroduction.",
     g: ["Gelsomino M et al. BMJ Case Rep 2021", "Vandenplas Y et al. JPGN 2024"],
     p: "A positive prick test is a question, not an answer.",
     dp: "Each extra exclusion narrows the mother's diet; plan calcium and protein sources whenever an elimination is tried.",
     pre: { view: "outside", colour: "red" },
     fx: { ok: { cap: "The test is read for what it is.", hl: "gut" }, bad: { cap: "A second food is cut on the strength of a skin test.", kind: "warn" } } },
   { s: "Admission", v: "Three days after egg is removed, she passes a large amount of blood and is admitted. Haemoglobin has fallen to 95 g/L (from 125), ferritin is 18 ng/mL. Coagulation, CRP, CMV tests, stool culture and parasitology, faecal calprotectin, abdominal ultrasound and scintigraphy are all normal. Proctoscopy shows proctitis with small aphthae; biopsies show a lymphoplasmacytic infiltrate with 25 eosinophils per high-power field. Five days after egg removal the bleeding stops.",
     q: "How do you find out whether egg was really the trigger?",
     o: [["Reintroduce egg, and cow's milk, into the mother's diet and watch for the bleeding to return", "A food is only proven as the cause if symptoms come back on reintroduction.", 1],
         ["Assume egg was the cause because the bleeding stopped", "Bleeding in these infants often settles on its own; timing alone proves nothing.", 0],
         ["Keep both foods out of the mother's diet until the baby is 1 year old", "Months of restriction with no proof.", 0],
         ["Repeat the biopsy", "Histology cannot identify a food trigger.", 0]],
     a: "Egg and cow's milk were reintroduced at 4 months 5 days, about 10 days after the bleeding stopped. The bleeding did not come back, and had not returned at 11 months of age. Because removing cow's milk did not stop the bleeding and reintroducing egg did not restart it, the authors conclude this was not food protein-induced allergic proctocolitis.",
     g: ["Gelsomino M et al. BMJ Case Rep 2021"],
     p: "No reintroduction, no diagnosis.",
     pre: { view: "inside", colour: "red", stool: "normal" },
     fx: { ok: { cap: "Both foods return to the mother's diet and the stools stay clear.", set: { colour: "normal" }, hl: "gut" }, bad: { cap: "A food-allergy label sticks without proof.", kind: "warn" } } },
   { s: "Next time", v: "Another exclusively breastfed 6-week-old has had small streaks of bright blood for 3 weeks. She is well and growing, with no fissure and no warning signs.",
     q: "What does this case suggest you do?",
     o: [["Consider benign non-allergic proctocolitis: keep breastfeeding, wait at least 2 months before any elimination diet, and investigate only if warning signs appear", "The authors' proposed approach for exactly this picture.", 1],
         ["Start a multi-food maternal elimination diet now", "The approach this case argues against.", 0],
         ["Order allergy tests to guide the diet", "Tests show sensitisation, not cause.", 0],
         ["Arrange endoscopy", "Only if warning signs develop or bleeding persists beyond 1 year.", 0]],
     a: "The authors propose that non-allergic benign infantile proctocolitis should be the first diagnosis suspected when an infant is under 6 months old, the bleeding has lasted less than 2 months and is bright and small, there is no fissure, and the infant is healthy with no warning signs. They would then wait at least 2 months before any elimination diet, and investigate further only if warning signs appear or bleeding persists beyond 1 year. They cite the only randomised trial, in which eliminating trigger foods did not change the duration or severity of bleeding.",
     g: ["Gelsomino M et al. BMJ Case Rep 2021"],
     p: "Name the benign option before reaching for a diet.",
     pre: { view: "outside", colour: "red" },
     fx: { ok: { cap: "Breastfeeding protected; the diet stays unchanged.", set: { colour: "normal" } }, bad: { cap: "Another mother starts an unnecessary diet.", kind: "warn" } } }
  ],
  refs: ["Gelsomino M, Sinatti D, Miceli Sopo S. Non-allergic benign infantile proctocolitis: a neglected nosographic entity. BMJ Case Rep 2021;14:e244918", "Vandenplas Y et al. J Pediatr Gastroenterol Nutr 2024;78:386-413"] },

{ id: "volvulus-second-look", engine: "home", track: "surg", aud: ["paed"], level: "Advanced", min: 6,
  pub: { cite: "Alvarez-Lopez O, Hernandez-Lopez K, Castañeda JA, Herrera EN. Second-look surgery for intestinal salvage in a neonate with midgut volvulus and intestinal malrotation: a case report. Cureus 2025;17(7):e88600", url: "https://doi.org/10.7759/cureus.88600" },
  title: "Bilious vomiting on day 5",
  sub: "Midgut volvulus with ischaemic bowel saved by a second-look operation",
  pt: { tag: "Day 5", name: "Baby girl, Alvarez-Lopez 2025", line: "Five-day-old girl with bilious vomiting, a distended abdomen and no stool for 48 hours." },
  vitals: [["Age", "Day 5"], ["WBC", "14,000/μL"], ["Stool", "None 48 h"]],
  scene: { view: "outside", spit: 2, spitCol: "bile", distension: .45, stress: .55, hr: 168, temp: 36.9 },
  steps: [
   { s: "Emergency department", v: "Bilious vomiting, abdominal distension and no stool for 48 hours. Vital signs are normal for age. White cell count 14,000/μL. The abdominal X-ray shows no distal gas. There is no peritonism.",
     q: "What is the next step?",
     o: [["Treat as midgut volvulus: stop feeds, decompress the stomach, give IV fluids and go for urgent surgical exploration", "Bilious vomiting is a surgical emergency, and exploration should not wait for imaging to confirm volvulus.", 1],
         ["Book a contrast study for the next morning", "Waiting risks bowel necrosis.", 0],
         ["Ultrasound, and discharge if there is no whirlpool sign", "The whirlpool sign is present in only about 64% of cases.", 0],
         ["Offer small feeds and observe", "Feeding a possibly twisted bowel is dangerous.", 0]],
     a: "Midgut volvulus most often presents with sudden bilious vomiting between the third and fifth day of life and is a surgical emergency until proven otherwise. The authors note that when volvulus is suspected, urgent exploration should go ahead even without radiographic confirmation, to avoid massive resections and short bowel syndrome. Here the plain X-ray showing obstruction prompted exploratory laparotomy.",
     g: ["Alvarez-Lopez O et al. Second-look surgery for intestinal salvage in a neonate with midgut volvulus. Cureus 2025", "Langer JC. Intestinal rotation abnormalities and midgut volvulus. Surg Clin North Am 2017"],
     p: "Green vomit: theatre first, pictures later if needed.",
     pre: { view: "outside", spit: 2, spitCol: "bile", distension: .45, stress: .55, hr: 168 },
     fx: { ok: { cap: "Feeds stopped, stomach decompressed, straight to theatre.", set: { view: "inside", spit: 0, fill: .05, dusky: .7 }, hl: "gut" }, bad: { cap: "The twisted bowel loses its blood supply while she waits.", set: { view: "inside", dusky: 1, distension: .8, stress: .85, hr: 186 }, hl: "gut", kind: "bad" } } },
   { s: "First laparotomy", v: "The small bowel is twisted around its mesentery. After detorsion the loops are ischaemic throughout. Ladd's bands are divided and the mesentery is broadened, but the ischaemic changes persist.",
     q: "What should the surgeons do now?",
     o: [["Avoid resecting bowel of doubtful viability, and plan a second-look laparotomy in 48 hours", "Bowel that looks ischaemic after detorsion often recovers.", 1],
         ["Resect all the ischaemic small bowel now", "Risks an avoidable short bowel syndrome.", 0],
         ["Close and plan no further operation", "Loses the chance to check viability and finish the repair.", 0],
         ["Twist the bowel back to its original position", "Detorsion is the treatment.", 0]],
     a: "A second-look operation was planned at 48 hours to complete the Ladd procedure and reassess viability. The authors explain that bowel often looks congested and ischaemic after detorsion but recovers with time, so the resection needed may be smaller than first estimated; second-look surgery has been used to save bowel in such cases.",
     g: ["Alvarez-Lopez O et al. Cureus 2025"],
     p: "When viability is in doubt, wait and look again.",
     pre: { view: "inside", dusky: .8, distension: .35, stress: .4, hr: 160, spit: 0 },
     fx: { ok: { cap: "Doubtful bowel kept; second look in 48 hours.", set: { dusky: .6 }, hl: "gut" }, bad: { cap: "Bowel that might have recovered is removed.", kind: "bad" } } },
   { s: "Second look", v: "At 48 hours the small bowel is pink and viable throughout. The Ladd procedure is completed with an appendectomy, and no resection is needed.",
     q: "Which steps make up the Ladd procedure?",
     o: [["Counter-clockwise detorsion, division of Ladd's bands, broadening of the mesenteric base, small bowel placed to the right and colon to the left, usually with appendectomy", "The surgical principles described in the case.", 1],
         ["Detorsion and suturing the bowel to the abdominal wall only", "Not the Ladd procedure.", 0],
         ["Resection of the caecum", "Not part of the procedure.", 0],
         ["Gastrostomy alone", "Does not treat malrotation.", 0]],
     a: "The authors list the Ladd principles as counter-clockwise detorsion, division of Ladd's bands, broadening of the mesenteric root, placing the small intestine on the right and the colon on the left, and usually appendectomy, with bowel viability checked after detorsion and at the end of the operation.",
     g: ["Alvarez-Lopez O et al. Cureus 2025"],
     p: "Check viability twice: after detorsion and before closing.",
     pre: { view: "inside", dusky: .2, distension: .15, stress: .25, hr: 150 },
     fx: { ok: { cap: "Healthy pink bowel, nothing removed.", set: { dusky: 0, distension: 0 }, hl: "gut" }, bad: { cap: "An incomplete repair.", kind: "warn" } } },
   { s: "Why it mattered", v: "She restarts oral feeds on day 6 after surgery, goes home on day 7, and is well at 7 months.",
     q: "What complication did keeping the bowel most likely prevent?",
     o: [["Short bowel syndrome and intestinal failure from a large resection", "The main long-term harm of massive bowel loss.", 1],
         ["Pyloric stenosis", "Unrelated.", 0],
         ["Cow's milk allergy", "Unrelated.", 0],
         ["Gastro-oesophageal reflux disease", "Not the main risk here.", 0]],
     a: "Feeds restarted on postoperative day 6, she was discharged on day 7, and there were no complications at 7 months. The authors stress that second-look surgery can prevent irreversible necrosis and extensive resection, and that short bowel syndrome is a leading cause of morbidity and mortality in these infants.",
     g: ["Alvarez-Lopez O et al. Cureus 2025"],
     p: "Every centimetre of bowel saved is future nutrition.",
     dp: "After a long ischaemic insult, restart feeds gradually with human milk where available and watch tolerance and growth.",
     pre: { view: "outside", dusky: 0, distension: 0, stress: .05, hr: 136, spit: 0, feeding: true, fill: .4 },
     fx: { ok: { cap: "Home on day 7, well at 7 months.", set: { stress: 0 } }, bad: { cap: "Short bowel syndrome is the harm second-look surgery aims to prevent.", kind: "warn" } } }
  ],
  refs: ["Alvarez-Lopez O, Hernandez-Lopez K, Castañeda JA, Herrera EN. Second-look surgery for intestinal salvage in a neonate with midgut volvulus and intestinal malrotation: a case report. Cureus 2025;17:e88600", "Langer JC. Surg Clin North Am 2017;97:147-59"] }
];
